def split_addresses(apps, schema_editor):
    """今の住所の行を、一括申請ツールの都道府県・市区町村に分けて入れる（T46-D4。空の列を埋めるだけ）。"""
    from services import addresses

    WorkerAddress = apps.get_model("workers", "WorkerAddress")
    for address in WorkerAddress.objects.all():
        split = addresses.split(address.address)
        if split.ok:
            address.prefecture_code = split.prefecture_code
            address.municipality_code = split.municipality_code
            address.address_rest = split.rest
            address.save(update_fields=["prefecture_code", "municipality_code", "address_rest"])


